insert into pqbr.catalogo_erros (codigo, categoria, descricao, exemplo, prevencao, severidade, papeis_interessados) values
('ERR-PER-01','personagem','Personagem inconsistente entre cenas: barba, cabelo e camiseta mudam de uma cena para outra.',
 '{"tema":"lote-2510 (cenas Higgsfield/Runway)","caminho":"docs/pesquisas/lote-2510/"}',
 'Repetir a ficha do personagem palavra por palavra em todo prompt (idade, cabelo, barba, roupa e cor); usar a mesma imagem de referência em todas as cenas; o Auditor compara a ficha cena a cena.','alta','{lider-editorial,auditor}'),
('ERR-ROT-01','roteiro','Detalhe do roteiro ignorado na imagem: café escuro em vídeo sobre "café fraco".',
 '{"tema":"Por que chamamos café fraco de chá de bico de chaleira?","caminho":"docs/pesquisas/lote-2510/chamamos-cafe-fraco-de-cha-de-bico-de-chaleira"}',
 'Extrair do roteiro os atributos visuais obrigatórios (ex.: café ralo, cor de chá claro) e escrevê-los de forma explícita e literal em cada prompt da cena; checagem: o Auditor confere o atributo-chave.','alta','{lider-editorial,auditor}'),
('ERR-EST-01','estilo','Cenário repetitivo: o mesmo fundo/enquadramento em várias cenas seguidas.',
 '{"tema":"lote-2510","caminho":"docs/pesquisas/lote-2510/"}',
 'Variar ambiente e enquadramento a cada 2–4 s (CONTRATO §16.7 [CENAS]); a lista de cenas não pode repetir o mesmo par ambiente+enquadramento em cenas consecutivas.','media','{lider-editorial,auditor}'),
('ERR-EST-02','estilo','Cena fora do cenário: elemento ou ambiente que não pertence ao tema/fala da cena.',
